import sys
from collections import Counter

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def can_rearrange(s):
    count = Counter(s)
    for p in range(2, len(s) + 1):
        if is_prime(p):
            block_size = len(s) // p
            if any(count[c] % block_size != 0 for c in count):
                return False
    return True

def construct_string(s):
    count = Counter(s)
    result = []
    for _ in range(len(s) // min(count.values())):
        for char in sorted(count, key=lambda x: (count[x], x)):
            result.append(char)
            count[char] -= 1
    return ''.join(result)

s = sys.stdin.read().strip()
if can_rearrange(s):
    print("YES")
    print(construct_string(s))
else:
    print("NO")
